INSERT INTO admin_tasks (assignee, status, status_date, comment, note) VALUES
('Я', 'open', NULL, 'Определить цену и объём пакета документов для докупки',
 'Когда лимит документов за месяц исчерпан, пользователь сможет докупить пакет документов (или сменить тариф). Нужно определить: сколько документов в пакете и цену. После этого подключим реальную оплату пакета через Robokassa. Сейчас кнопка «Докупить пакет» показывает заглушку «скоро».');
